func TestRenderTable_AlignsColumns(t *testing.T) {
	rows := [][]string{{"id", "name"}, {"1", "alice"}, {"22", "bob"}}
	out := RenderTable(rows)
	lines := strings.Split(strings.TrimSpace(out), "\n")
	if len(lines) != 3 {
